    23  /**
    24   * FuUswidFirmware:
    25   *
    26   * A uSWID header with multiple optionally-compressed coSWID CBOR sections.
    27   *
    28   * See also: [class@FuCoswidFirmware]
    29   */
    30
    31  typedef struct {
    32          guint8 hdrver;
    33          FuUswidPayloadCompression compression;
    34  } FuUswidFirmwarePrivate;
    35
    36  G_DEFINE_TYPE_WITH_PRIVATE(FuUswidFirmware, fu_uswid_firmware, FU_TYPE_FIRMWARE)
    37  #define GET_PRIVATE(o) (fu_uswid_firmware_get_instance_private(o))
    38
    39  #define FU_USWID_FIRMARE_MINIMUM_HDRVER 1
    40
    41  static void
    42  fu_uswid_firmware_export(FuFirmware *firmware, FuFirmwareExportFlags flags, XbBuilderNode *bn)
    43  {
    44          FuUswidFirmware *self = FU_USWID_FIRMWARE(firmware);
    45          FuUswidFirmwarePrivate *priv = GET_PRIVATE(self);
    46          fu_xmlb_builder_insert_kx(bn, "hdrver", priv->hdrver);
    47          if (priv->compression != FU_USWID_PAYLOAD_COMPRESSION_NONE) {
    48                  fu_xmlb_builder_insert_kv(
    49                      bn,
    50                      "compression",
    51                      fu_uswid_payload_compression_to_string(priv->compression));
    52          }
    53  }
