   180  static GByteArray *
   181  fu_uswid_firmware_write(FuFirmware *firmware, GError **error)
   182  {
   183          FuUswidFirmware *self = FU_USWID_FIRMWARE(firmware);
   184          FuUswidFirmwarePrivate *priv = GET_PRIVATE(self);
   185          g_autoptr(FuStructUswid) buf = fu_struct_uswid_new();
   186          g_autoptr(GByteArray) payload = g_byte_array_new();
   187          g_autoptr(GBytes) payload_blob = NULL;
   188          g_autoptr(GPtrArray) images = fu_firmware_get_images(firmware);
   189
   190          /* generate early so we know the size */
   191          for (guint i = 0; i < images->len; i++) {
   192                  FuFirmware *firmware_coswid = g_ptr_array_index(images, i);
   193                  g_autoptr(GBytes) fw = fu_firmware_write(firmware_coswid, error);
   194                  if (fw == NULL)
   195                          return NULL;
   196                  fu_byte_array_append_bytes(payload, fw);
   197          }
   198
   199          /* zlibify */
   200          if (priv->compression == FU_USWID_PAYLOAD_COMPRESSION_ZLIB) {
   201                  g_autoptr(GConverter) conv = NULL;
   202                  g_autoptr(GInputStream) istream1 = NULL;
   203                  g_autoptr(GInputStream) istream2 = NULL;
   204
   205                  conv = G_CONVERTER(g_zlib_compressor_new(G_ZLIB_COMPRESSOR_FORMAT_ZLIB, -1));
   206                  istream1 = g_memory_input_stream_new_from_data(payload->data, payload->len, NULL);
   207                  istream2 = g_converter_input_stream_new(istream1, conv);
   208                  payload_blob = fu_input_stream_read_bytes(istream2, 0, G_MAXSIZE, error);
   209                  if (payload_blob == NULL)
   210                          return NULL;
   211          } else if (priv->compression == FU_USWID_PAYLOAD_COMPRESSION_LZMA) {
   212                  g_autoptr(GBytes) payload_tmp = g_bytes_new(payload->data, payload->len);
   213                  payload_blob = fu_lzma_compress_bytes(payload_tmp, error);
   214                  if (payload_blob == NULL)
   215                          return NULL;
   216          } else {
   217                  payload_blob = g_bytes_new(payload->data, payload->len);
   218          }
   219
   220          /* pack */
   221          fu_struct_uswid_set_hdrver(buf, priv->hdrver);
   222          fu_struct_uswid_set_payloadsz(buf, g_bytes_get_size(payload_blob));
   223          if (priv->hdrver >= 3) {
   224                  guint8 flags = 0;
   225                  if (priv->compression != FU_USWID_PAYLOAD_COMPRESSION_NONE)
   226                          flags |= FU_USWID_HEADER_FLAG_COMPRESSED;
   227                  fu_struct_uswid_set_flags(buf, flags);
   228                  fu_struct_uswid_set_compression(buf, priv->compression);
   229          } else if (priv->hdrver >= 2) {
   230                  guint8 flags = 0;
   231                  if (priv->compression != FU_USWID_PAYLOAD_COMPRESSION_NONE) {
   232                          if (priv->compression != FU_USWID_PAYLOAD_COMPRESSION_ZLIB) {
   233                                  g_set_error_literal(error,
   234                                                      FWUPD_ERROR,
   235                                                      FWUPD_ERROR_NOT_SUPPORTED,
   236                                                      "hdrver 0x02 only supports zlib compression");
   237                                  return NULL;
   238                          }
   239                          flags |= FU_USWID_HEADER_FLAG_COMPRESSED;
   240                  }
   241                  fu_struct_uswid_set_flags(buf, flags);
   242                  g_byte_array_set_size(buf, buf->len - 1);
   243                  fu_struct_uswid_set_hdrsz(buf, buf->len);
   244          } else {
   245                  g_byte_array_set_size(buf, buf->len - 2);
   246                  fu_struct_uswid_set_hdrsz(buf, buf->len);
   247          }
   248          fu_byte_array_append_bytes(buf, payload_blob);
   249
   250          /* success */
   251          return g_steal_pointer(&buf);
   252  }
