   254  static gboolean
   255  fu_uswid_firmware_build(FuFirmware *firmware, XbNode *n, GError **error)
   256  {
   257          FuUswidFirmware *self = FU_USWID_FIRMWARE(firmware);
   258          FuUswidFirmwarePrivate *priv = GET_PRIVATE(self);
   259          const gchar *str;
   260          guint64 tmp;
   261
   262          /* simple properties */
   263          tmp = xb_node_query_text_as_uint(n, "hdrver", NULL);
   264          if (tmp != G_MAXUINT64 && tmp <= G_MAXUINT8)
   265                  priv->hdrver = tmp;
   266
   267          /* simple properties */
   268          str = xb_node_query_text(n, "compression", NULL);
   269          if (str != NULL) {
   270                  priv->compression = fu_uswid_payload_compression_from_string(str);
   271                  if (priv->compression == FU_USWID_PAYLOAD_COMPRESSION_NONE) {
   272                          g_set_error(error,
   273                                      FWUPD_ERROR,
   274                                      FWUPD_ERROR_INVALID_DATA,
   275                                      "invalid compression type %s",
   276                                      str);
   277                          return FALSE;
   278                  }
   279          } else {
   280                  priv->compression = FU_USWID_PAYLOAD_COMPRESSION_NONE;
   281          }
   282
   283          /* success */
   284          return TRUE;
   285  }
