   287  static void
   288  fu_uswid_firmware_init(FuUswidFirmware *self)
   289  {
   290          FuUswidFirmwarePrivate *priv = GET_PRIVATE(self);
   291          priv->hdrver = FU_USWID_FIRMARE_MINIMUM_HDRVER;
   292          priv->compression = FU_USWID_PAYLOAD_COMPRESSION_NONE;
   293          fu_firmware_add_flag(FU_FIRMWARE(self), FU_FIRMWARE_FLAG_HAS_STORED_SIZE);
   294          fu_firmware_add_flag(FU_FIRMWARE(self), FU_FIRMWARE_FLAG_ALWAYS_SEARCH);
   295          fu_firmware_set_images_max(FU_FIRMWARE(self), 2000);
   296          g_type_ensure(FU_TYPE_COSWID_FIRMWARE);
   297  }
