   118  /* @userdata: a #FuCoswidFirmware */
   119  static gboolean
   120  fu_coswid_firmware_parse_meta(cbor_item_t *item, gpointer user_data, GError **error)
   121  {
   122          FuCoswidFirmware *self = FU_COSWID_FIRMWARE(user_data);
   123          FuCoswidFirmwarePrivate *priv = GET_PRIVATE(self);
   124          struct cbor_pair *pairs = cbor_map_handle(item);
   125
   126          for (gsize i = 0; i < cbor_map_size(item); i++) {
   127                  FuCoswidTag tag_id = 0;
   128                  if (!fu_coswid_read_tag(pairs[i].key, &tag_id, error))
   129                          return FALSE;
   130                  if (tag_id == FU_COSWID_TAG_SUMMARY) {
   131                          g_free(priv->summary);
   132                          priv->summary = fu_coswid_read_string(pairs[i].value, error);
   133                          if (priv->summary == NULL) {
   134                                  g_prefix_error(error, "failed to parse summary: ");
   135                                  return FALSE;
   136                          }
   137                  } else if (tag_id == FU_COSWID_TAG_COLLOQUIAL_VERSION) {
   138                          g_free(priv->colloquial_version);
   139                          priv->colloquial_version = fu_coswid_read_string(pairs[i].value, error);
   140                          if (priv->colloquial_version == NULL) {
   141                                  g_prefix_error(error, "failed to parse colloquial-version: ");
   142                                  return FALSE;
   143                          }
   144                  } else {
   145                          g_debug("unhandled tag %s from %s",
   146                                  fu_coswid_tag_to_string(tag_id),
   147                                  fu_coswid_tag_to_string(FU_COSWID_TAG_SOFTWARE_META));
   148                  }
   149          }
   150
   151          /* success */
   152          return TRUE;
   153  }
