   200  /* @userdata: a #FuCoswidFirmwarePayload */
   201  static gboolean
   202  fu_coswid_firmware_parse_hash(cbor_item_t *item, gpointer user_data, GError **error)
   203  {
   204          FuCoswidFirmwarePayload *payload = (FuCoswidFirmwarePayload *)user_data;
   205          g_autoptr(FuCoswidFirmwareHash) hash = g_new0(FuCoswidFirmwareHash, 1);
   206          g_autoptr(cbor_item_t) hash_item_alg_id = NULL;
   207          g_autoptr(cbor_item_t) hash_item_value = NULL;
   208
   209          /* sanity check */
   210          if (!cbor_isa_array(item)) {
   211                  g_set_error_literal(error,
   212                                      FWUPD_ERROR,
   213                                      FWUPD_ERROR_INVALID_DATA,
   214                                      "hash item is not an array");
   215                  return FALSE;
   216          }
   217          hash_item_alg_id = cbor_array_get(item, 0);
   218          hash_item_value = cbor_array_get(item, 1);
   219          if (hash_item_alg_id == NULL || hash_item_value == NULL) {
   220                  g_set_error_literal(error,
   221                                      FWUPD_ERROR,
   222                                      FWUPD_ERROR_INVALID_DATA,
   223                                      "invalid hash item");
   224                  return FALSE;
   225          }
   226          if (!cbor_isa_uint(hash_item_alg_id)) {
   227                  g_set_error_literal(error,
   228                                      FWUPD_ERROR,
   229                                      FWUPD_ERROR_INVALID_DATA,
   230                                      "hash alg-id item is not a uint");
   231                  return FALSE;
   232          }
   233
   234          /* success */
   235          hash->alg_id = cbor_get_uint8(hash_item_alg_id);
   236          hash->value = g_byte_array_new();
   237          g_byte_array_append(hash->value,
   238                              cbor_bytestring_handle(hash_item_value),
   239                              cbor_bytestring_length(hash_item_value));
   240          g_ptr_array_add(payload->hashes, g_steal_pointer(&hash));
   241          return TRUE;
   242  }
