   245  static gboolean
   246  fu_coswid_firmware_parse_hash_array(cbor_item_t *item, gpointer user_data, GError **error)
   247  {
   248          for (guint j = 0; j < cbor_array_size(item); j++) {
   249                  g_autoptr(cbor_item_t) value = cbor_array_get(item, j);
   250                  if (!fu_coswid_firmware_parse_hash(value, user_data, error))
   251                          return FALSE;
   252          }
   253          return TRUE;
