    17  /**
    18   * fu_coswid_read_string:
    19   * @item: a #cbor_item_t
    20   * @value: read value
    21   * @error: (nullable): optional return location for an error
    22   *
    23   * Reads a string value.
    24   *
    25   * Returns: %TRUE for success
    26   *
    27   * Since: 1.9.17
    28   **/
    29  gchar *
    30  fu_coswid_read_string(cbor_item_t *item, GError **error)
    31  {
    32          g_return_val_if_fail(item != NULL, NULL);
    33          g_return_val_if_fail(error == NULL || *error == NULL, NULL);
    34
    35          if (!cbor_isa_string(item)) {
    36                  g_set_error_literal(error,
    37                                      FWUPD_ERROR,
    38                                      FWUPD_ERROR_INVALID_DATA,
    39                                      "item is not a string");
    40                  return NULL;
    41          }
