   256  /* @userdata: a #FuCoswidFirmware */
   257  static gboolean
   258  fu_coswid_firmware_parse_file(cbor_item_t *item, gpointer user_data, GError **error)
   259  {
   260          FuCoswidFirmware *self = FU_COSWID_FIRMWARE(user_data);
   261          FuCoswidFirmwarePrivate *priv = GET_PRIVATE(self);
   262          struct cbor_pair *pairs = cbor_map_handle(item);
   263          g_autoptr(FuCoswidFirmwarePayload) payload = fu_coswid_firmware_payload_new();
   264
   265          for (gsize i = 0; i < cbor_map_size(item); i++) {
   266                  FuCoswidTag tag_id = 0;
   267                  if (!fu_coswid_read_tag(pairs[i].key, &tag_id, error))
   268                          return FALSE;
   269                  if (tag_id == FU_COSWID_TAG_FS_NAME) {
   270                          g_free(payload->name);
   271                          payload->name = fu_coswid_read_string(pairs[i].value, error);
   272                          if (payload->name == NULL) {
   273                                  g_prefix_error(error, "failed to parse payload name: ");
   274                                  return FALSE;
   275                          }
   276                  } else if (tag_id == FU_COSWID_TAG_SIZE) {
   277                          if (!fu_coswid_read_u64(pairs[i].value, &payload->size, error))
   278                                  return FALSE;
   279                  } else if (tag_id == FU_COSWID_TAG_HASH) {
   280                          if (cbor_isa_array(pairs[i].value) &&
   281                              cbor_array_size(pairs[i].value) >= 1) {
   282                                  g_autoptr(cbor_item_t) value = cbor_array_get(pairs[i].value, 0);
   283                                  /* we can't use fu_coswid_parse_one_or_many() here as
   284                                   * the hash is an array, not a map -- for some reason */
   285                                  if (cbor_isa_array(value)) {
   286                                          if (!fu_coswid_firmware_parse_hash_array(pairs[i].value,
   287                                                                                   payload,
   288                                                                                   error))
   289                                                  return FALSE;
   290                                  } else {
   291                                          if (!fu_coswid_firmware_parse_hash(pairs[i].value,
   292                                                                             payload,
   293                                                                             error))
   294                                                  return FALSE;
   295                                  }
   296                          } else {
   297                                  g_set_error(error,
   298                                              FWUPD_ERROR,
   299                                              FWUPD_ERROR_INVALID_DATA,
   300                                              "hashes neither an array or array of array");
   301                                  return FALSE;
   302                          }
   303                  } else {
   304                          g_debug("unhandled tag %s from %s",
   305                                  fu_coswid_tag_to_string(tag_id),
   306                                  fu_coswid_tag_to_string(FU_COSWID_TAG_FILE));
   307                  }
   308          }
   309
   310          /* success */
   311          g_ptr_array_add(priv->payloads, g_steal_pointer(&payload));
   312          return TRUE;
   313  }
