   402  /* @userdata: a #FuCoswidFirmware */
   403  static gboolean
   404  fu_coswid_firmware_parse_entity(cbor_item_t *item, gpointer user_data, GError **error)
   405  {
   406          FuCoswidFirmware *self = FU_COSWID_FIRMWARE(user_data);
   407          FuCoswidFirmwarePrivate *priv = GET_PRIVATE(self);
   408          struct cbor_pair *pairs = cbor_map_handle(item);
   409          guint entity_role_cnt = 0;
   410          g_autoptr(FuCoswidFirmwareEntity) entity = g_new0(FuCoswidFirmwareEntity, 1);
   411
   412          for (gsize i = 0; i < cbor_map_size(item); i++) {
   413                  FuCoswidTag tag_id = 0;
   414                  if (!fu_coswid_read_tag(pairs[i].key, &tag_id, error))
   415                          return FALSE;
   416                  if (tag_id == FU_COSWID_TAG_ENTITY_NAME) {
   417                          g_free(entity->name);
   418                          entity->name = fu_coswid_read_string(pairs[i].value, error);
   419                          if (entity->name == NULL) {
   420                                  g_prefix_error(error, "failed to parse entity name: ");
   421                                  return FALSE;
   422                          }
   423                  } else if (tag_id == FU_COSWID_TAG_REG_ID) {
   424                          g_free(entity->regid);
   425                          entity->regid = fu_coswid_read_string(pairs[i].value, error);
   426                          if (entity->regid == NULL) {
   427                                  g_prefix_error(error, "failed to parse entity regid: ");
   428                                  return FALSE;
   429                          }
   430                  } else if (tag_id == FU_COSWID_TAG_ROLE) {
   431                          if (cbor_isa_uint(pairs[i].value)) {
   432                                  FuCoswidEntityRole role = cbor_get_uint8(pairs[i].value);
   433                                  entity->roles[entity_role_cnt++] = role;
   434                          } else if (cbor_isa_array(pairs[i].value)) {
   435                                  for (guint j = 0; j < cbor_array_size(pairs[i].value); j++) {
   436                                          g_autoptr(cbor_item_t) value =
   437                                              cbor_array_get(pairs[i].value, j);
   438                                          if (!cbor_isa_uint(value)) {
   439                                                  g_set_error_literal(error,
   440                                                                      FWUPD_ERROR,
   441                                                                      FWUPD_ERROR_INVALID_DATA,
   442                                                                      "entity role is not a uint");
   443                                                  return FALSE;
   444                                          }
   445                                          if (entity_role_cnt >= G_N_ELEMENTS(entity->roles)) {
   446                                                  g_set_error_literal(error,
   447                                                                      FWUPD_ERROR,
   448                                                                      FWUPD_ERROR_INVALID_DATA,
   449                                                                      "too many roles");
   450                                                  return FALSE;
   451                                          }
   452                                          entity->roles[entity_role_cnt++] = cbor_get_uint8(value);
   453                                  }
   454                          } else {
   455                                  g_set_error_literal(error,
   456                                                      FWUPD_ERROR,
   457                                                      FWUPD_ERROR_INVALID_DATA,
   458                                                      "entity role item is not an uint or array");
   459                                  return FALSE;
   460                          }
   461                  } else {
   462                          g_debug("unhandled tag %s from %s",
   463                                  fu_coswid_tag_to_string(tag_id),
   464                                  fu_coswid_tag_to_string(FU_COSWID_TAG_ENTITY));
   465                  }
   466          }
   467
   468          /* success */
   469          g_ptr_array_add(priv->entities, g_steal_pointer(&entity));
   470          return TRUE;
   471  }
