   704  static void
   705  fu_coswid_firmware_write_payload(cbor_item_t *root, FuCoswidFirmwarePayload *payload)
   706  {
   707          g_autoptr(cbor_item_t) item_payload = cbor_new_indefinite_map();
   708          g_autoptr(cbor_item_t) item_file = cbor_new_indefinite_map();
   709          if (payload->name != NULL) {
   710                  fu_coswid_write_tag_string(item_file, FU_COSWID_TAG_FS_NAME, payload->name);
   711          }
   712          if (payload->size != 0) {
   713                  fu_coswid_write_tag_u64(item_file, FU_COSWID_TAG_SIZE, payload->size);
   714          }
   715          if (payload->hashes->len > 0) {
   716                  g_autoptr(cbor_item_t) item_hashes = cbor_new_indefinite_array();
   717                  for (guint j = 0; j < payload->hashes->len; j++) {
   718                          FuCoswidFirmwareHash *hash = g_ptr_array_index(payload->hashes, j);
   719                          fu_coswid_firmware_write_hash(item_hashes, hash);
   720                  }
   721                  fu_coswid_write_tag_item(item_file, FU_COSWID_TAG_HASH, item_hashes);
   722          }
   723          fu_coswid_write_tag_item(item_payload, FU_COSWID_TAG_FILE, item_file);
   724          if (!cbor_array_push(root, item_payload))
   725                  g_critical("failed to push to indefinite array");
   726  }
