   856  static gboolean
   857  fu_coswid_firmware_build_entity(FuCoswidFirmware *self, XbNode *n, GError **error)
   858  {
   859          FuCoswidFirmwarePrivate *priv = GET_PRIVATE(self);
   860          const gchar *tmp;
   861          guint entity_role_cnt = 0;
   862          FuCoswidEntityRole role;
   863          g_autoptr(GPtrArray) roles = NULL;
   864          g_autoptr(FuCoswidFirmwareEntity) entity = g_new0(FuCoswidFirmwareEntity, 1);
   865
   866          /* these are required */
   867          tmp = xb_node_query_text(n, "name", error);
   868          if (tmp == NULL)
   869                  return FALSE;
   870          entity->name = g_strdup(tmp);
   871          tmp = xb_node_query_text(n, "regid", error);
   872          if (tmp == NULL)
   873                  return FALSE;
   874          entity->regid = g_strdup(tmp);
   875
   876          /* optional */
   877          roles = xb_node_query(n, "role", 0, NULL);
   878          if (roles != NULL) {
   879                  for (guint i = 0; i < roles->len; i++) {
   880                          XbNode *c = g_ptr_array_index(roles, i);
   881                          tmp = xb_node_get_text(c);
   882                          role = fu_coswid_entity_role_from_string(tmp);
   883                          if (role == FU_COSWID_ENTITY_ROLE_UNKNOWN) {
   884                                  g_set_error(error,
   885                                              FWUPD_ERROR,
   886                                              FWUPD_ERROR_INVALID_DATA,
   887                                              "failed to parse entity role %s",
   888                                              tmp);
   889                                  return FALSE;
   890                          }
   891                          if (entity_role_cnt >= G_N_ELEMENTS(entity->roles)) {
   892                                  g_set_error_literal(error,
   893                                                      FWUPD_ERROR,
   894                                                      FWUPD_ERROR_INVALID_DATA,
   895                                                      "too many roles");
   896                                  return FALSE;
   897                          }
   898                          entity->roles[entity_role_cnt++] = role;
   899                  }
   900          }
   901
   902          /* success */
   903          g_ptr_array_add(priv->entities, g_steal_pointer(&entity));
   904          return TRUE;
   905  }
