   640  static gchar *
   641  fu_coswid_firmware_get_checksum(FuFirmware *firmware, GChecksumType csum_kind, GError **error)
   642  {
   643          FuCoswidFirmware *self = FU_COSWID_FIRMWARE(firmware);
   644          FuCoswidFirmwarePrivate *priv = GET_PRIVATE(self);
   645          FuCoswidHashAlg alg_id = FU_COSWID_HASH_ALG_UNKNOWN;
   646          struct {
   647                  GChecksumType kind;
   648                  FuCoswidHashAlg alg_id;
   649          } csum_kinds[] = {{G_CHECKSUM_SHA256, FU_COSWID_HASH_ALG_SHA256},
   650                            {G_CHECKSUM_SHA384, FU_COSWID_HASH_ALG_SHA384},
   651                            {G_CHECKSUM_SHA512, FU_COSWID_HASH_ALG_SHA512},
   652                            {0, FU_COSWID_HASH_ALG_UNKNOWN}};
   653
   654          /* convert to FuCoswidHashAlg */
   655          for (guint i = 0; csum_kinds[i].kind != 0; i++) {
   656                  if (csum_kinds[i].kind == csum_kind) {
   657                          alg_id = csum_kinds[i].alg_id;
   658                          break;
   659                  }
   660          }
   661          if (alg_id == FU_COSWID_HASH_ALG_UNKNOWN) {
   662                  g_set_error(error,
   663                              FWUPD_ERROR,
   664                              FWUPD_ERROR_NOT_SUPPORTED,
   665                              "cannot convert %s",
   666                              fwupd_checksum_type_to_string_display(csum_kind));
   667                  return NULL;
   668          }
   669
   670          /* find the correct hash kind */
   671          for (guint i = 0; i < priv->payloads->len; i++) {
   672                  FuCoswidFirmwarePayload *payload = g_ptr_array_index(priv->payloads, i);
   673                  for (guint j = 0; j < payload->hashes->len; j++) {
   674                          FuCoswidFirmwareHash *hash = g_ptr_array_index(payload->hashes, j);
   675                          if (hash->alg_id == alg_id)
   676                                  return fu_byte_array_to_string(hash->value);
   677                  }
   678          }
   679          g_set_error(error,
   680                      FWUPD_ERROR,
   681                      FWUPD_ERROR_NOT_SUPPORTED,
   682                      "no hash kind %s",
   683                      fwupd_checksum_type_to_string_display(csum_kind));
   684          return NULL;
   685  }
