   278  /**
   279   * fu_coswid_write_tag_s8:
   280   * @item: a #cbor_item_t
   281   * @tag: a #FuCoswidTag, e.g. %FU_COSWID_TAG_PAYLOAD
   282   * @value: signed integer
   283   *
   284   * Writes a #gint8 tag value.
   285   *
   286   * Returns: %TRUE for success
   287   *
   288   * Since: 1.9.17
   289   **/
   290  void
   291  fu_coswid_write_tag_s8(cbor_item_t *item, FuCoswidTag tag, gint8 value)
   292  {
   293          g_autoptr(cbor_item_t) key = cbor_build_uint8(tag);
   294          g_autoptr(cbor_item_t) val = cbor_new_int8();
   295          if (value >= 0) {
   296                  cbor_set_uint8(val, value);
