   298                  cbor_set_uint8(val, 0xFF - value);
   299                  cbor_mark_negint(val);
   300          }
   301          if (!cbor_map_add(item, (struct cbor_pair){.key = key, .value = val}))
   302                  g_critical("failed to push s8 to indefinite map");
   303  }
