   325  /**
   326   * fu_coswid_parse_one_or_many:
   327   * @item: a #cbor_item_t
   328   * @func: a function to call with each map value
   329   * @user_data: pointer value to pass to @func
   330   * @error: (nullable): optional return location for an error
   331   *
   332   * Parses an item that *may* be an array, calling @func on each map value.
   333   *
   334   * Returns: %TRUE for success
   335   *
   336   * Since: 1.9.17
   337   **/
   338  gboolean
   339  fu_coswid_parse_one_or_many(cbor_item_t *item,
   340                              FuCoswidItemFunc func,
   341                              gpointer user_data,
   342                              GError **error)
   343  {
   344          g_return_val_if_fail(error == NULL || *error == NULL, FALSE);
   345
   346          /* one */
   347          if (cbor_isa_map(item))
   348                  return func(item, user_data, error);
   349
   350          /* many */
   351          if (cbor_isa_array(item)) {
   352                  for (guint j = 0; j < cbor_array_size(item); j++) {
   353                          g_autoptr(cbor_item_t) value = cbor_array_get(item, j);
   354                          if (!cbor_isa_map(value)) {
   355                                  g_set_error_literal(error,
   356                                                      FWUPD_ERROR,
   357                                                      FWUPD_ERROR_INVALID_DATA,
   358                                                      "not an array of a map");
   359                                  return FALSE;
   360                          }
   361                          if (!func(value, user_data, error))
   362                                  return FALSE;
   363                  }
   364                  return TRUE;
   365          }
   366
   367          /* not sure what to do */
   368          g_set_error_literal(error,
   369                              FWUPD_ERROR,
   370                              FWUPD_ERROR_INVALID_DATA,
   371                              "neither an array or map");
   372          return FALSE;
   373  }
